const fs = require('fs')
const AF = Object.getPrototypeOf(async function () {}).constructor
const load = (f) => fs.readFileSync(f, 'utf8').replace('export const meta', 'const meta')
async function run(file, args, revival) {
  const calls = []
  const agent = async (prompt, o) => {
    calls.push({ label: o.label, model: o.model, prompt })
    switch (o.label) {
      case 'sort': return { counts: [{ home: 'FACTS', changes: 1 }], orientation: [], curator: [], summary: 's' }
      case 'land': return { landed: true, how: 'fast-forward', mainBefore: 'aaaaaaaaa', commits: ['c1 x'], pushed: ['main'], facts: [], stopped: '', summary: '' }
      case 'skill writer': return { nothing: false, exit: '0', base: 'bbbbbbbbb', commits: ['d1 skill'], parts: ['SKILL.md'], tail: '' }
      case 'skill fixes': return { exit: '0', commits: ['d2 fix'], parts: ['SKILL.md'], tail: '' }
      case 'page': return { published: true, url: 'U', version: 'v9', source: 'S', items: 3, newItems: 1, why: '', summary: '' }
      case 'push': return { committed: 'e1 folders', commits: ['d1 skill', 'd2 fix', 'e1 folders'], pushed: ['main', 'a', 'b'], stopped: '', summary: '' }
      case 'revival page': return revival
      case 'revival publish': return { published: true, url: 'https://claude.ai/artifact/8Gg1f2ZRXg462qmhcwx1T5', version: 'v27', why: '' }
      default: return 'text'
    }
  }
  const g = { args, agent, parallel: async (fs) => Promise.all(fs.map(f => f())), phase: () => {}, log: () => {}, workflow: async () => ({}) }
  const fn = new AF(...Object.keys(g), load(file))
  const r = await fn(...Object.values(g))
  return { calls, r }
}
;(async () => {
  const [NEW, ORIG] = process.argv.slice(2)
  const A = { batch: '27', base: 'b', landing: 'l' }
  const ok = { exit: '0', message: '', url: 'https://claude.ai/artifact/8Gg1f2ZRXg462qmhcwx1T5', committed: 'f1 Revival page: ...', paths: ['x'], pushed: ['main', 'a', 'b'], stopped: '' }
  const n = await run(NEW, A, ok), o = await run(ORIG, A, ok)
  for (let i = 0; i < o.calls.length; i++) if (o.calls[i].prompt !== n.calls[i].prompt) console.log('PROMPT DIFFERS', o.calls[i].label)
  console.log('orig agents', o.calls.length, 'new', n.calls.length, n.calls.slice(o.calls.length).map(c => c.label + '/' + c.model).join(', '))
  console.log('ok line:', n.r.line); console.log('ok stopped:', n.r.stopped)
  console.log('--- revival prompt\n' + n.calls.find(c => c.label === 'revival page').prompt)
  console.log('--- publish prompt\n' + n.calls.find(c => c.label === 'revival publish').prompt)
  const e2 = await run(NEW, A, { ...ok, exit: '2', message: 'update.py stops: PLAN.md: expected one match', committed: '', pushed: [], stopped: 'update.py stops: PLAN.md: expected one match' })
  console.log('exit2 agents', e2.calls.map(c => c.label).slice(-2).join(','), '| line:', e2.r.line, '| stopped:', e2.r.stopped)
  const rp = await run(NEW, { ...A, at: 'x' }, ok)
  console.log('replay agents', rp.calls.map(c => c.label).join(','), 'revival' in rp.r)
})()

